// Класифікація поїздок за geofence + евристики.
// Мета правил — не максимізувати бізнес-відсоток, а щоб число витримало
// перевірку. Логбук зі 100% бізнесу — червоний прапор, а не перемога.

const veh = $('Vehicles').first().json;
const fences = ($('Fetch Geofences').all() || []).map(i => i.json).flat();

function parseArea(area) {
  if (!area) return null;
  const c = /CIRCLE\s*\(\s*(-?[\d.]+)\s+(-?[\d.]+)\s*,\s*([\d.]+)\s*\)/i.exec(area);
  if (c) return { lat: +c[1], lon: +c[2], r: +c[3] };
  return null; // полігони поки не підтримуємо — geofences логбука кругові
}

function metres(lat1, lon1, lat2, lon2) {
  const R = 6371000, rad = Math.PI / 180;
  const dLat = (lat2 - lat1) * rad, dLon = (lon2 - lon1) * rad;
  const a = Math.sin(dLat / 2) ** 2 +
            Math.cos(lat1 * rad) * Math.cos(lat2 * rad) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

const circles = fences
  .map(f => ({ name: f.name || '', c: parseArea(f.area) }))
  .filter(f => f.c);

function zoneOf(lat, lon) {
  if (lat == null || lon == null) return null;
  let best = null, bestD = Infinity;
  for (const f of circles) {
    const d = metres(lat, lon, f.c.lat, f.c.lon);
    if (d <= f.c.r && d < bestD) { best = f.name; bestD = d; }
  }
  return best;
}

// Позиції за те саме вікно. Без них провал звʼязку всередині поїздки не
// видно взагалі: Traccar зшиває дірку прямою лінією й нічого не повідомляє.
// У логбук іде одна поїздка замість двох, із заниженою відстанню, а заїзд,
// де водій узяв чек, зникає безслідно.
const route = ($('Fetch Route').all() || [])
  .map(i => i.json).flat()
  .filter(p => p && p.fixTime)
  .map(p => ({ t: new Date(p.fixTime).getTime(), lat: p.latitude, lon: p.longitude }))
  .sort((a, b) => a.t - b.t);

// Найбільша пауза між сусідніми позиціями всередині поїздки і те, наскільки
// авто за цю паузу змістилося. Пауза без зміщення - просто стоянка.
function worstGap(fromIso, toIso) {
  const a = new Date(fromIso).getTime();
  const b = new Date(toIso).getTime();
  const seg = route.filter(p => p.t >= a && p.t <= b);
  let best = { min: 0, m: 0 };
  for (let i = 1; i < seg.length; i++) {
    const min = (seg[i].t - seg[i - 1].t) / 60000;
    if (min > best.min) {
      best = { min, m: metres(seg[i - 1].lat, seg[i - 1].lon, seg[i].lat, seg[i].lon) };
    }
  }
  return best;
}

const TZ = 'America/Moncton';
function localParts(iso) {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false, weekday: 'short'
  });
  const p = Object.fromEntries(fmt.formatToParts(new Date(iso)).map(x => [x.type, x.value]));
  return { date: `${p.year}-${p.month}-${p.day}`, hour: (+p.hour) % 24, weekday: p.weekday };
}

// Місця компанії: домашній офіс, орендований воркшоп, клієнти, постачальники.
// Поїздка між будь-якими двома з них — бізнесова. Список розширюваний:
// достатньо завести geofence з відповідним префіксом у Traccar.
const isBiz  = z => /^(HOME-OFFICE|SHOP-|CLIENT-|SUPPLIER-|SERVICE-|GOV-)/i.test(z || '');
const isPers = z => /^PERSONAL-/i.test(z || '');

// Застосунок призупиняє геолокацію на стоянці, тож перша точка поїздки
// зазвичай уже за сотні метрів від місця, де авто справді стояло. Тому
// зону старту, якої не видно, беремо з фінішу попередньої поїздки:
// фізично авто нікуди не дівалося між ними.
const trips = $input.all()
  .map(i => i.json)
  .filter(t => t && t.distance != null)
  .sort((a, b) => new Date(a.startTime) - new Date(b.startTime));

let carriedZone = null;

const out = [];
let drifted = 0;

for (const t of trips) {

  // Телефон на стоянці зрідка віддає точку з похибкою 60-180 м. Координата
  // стрибає на сотні метрів убік і назад, Traccar додає це до пройденої
  // відстані й ліпить «поїздку» там, де авто не рухалося. За дві години
  // стоянки так набігало шість фальшивих рейсів по 0.5-1.1 км.
  // Ознака: пройдено начебто кілометр, а між стартом і фінішем — метри.
  // filter.accuracy=50 у Traccar відсікає такі точки на вході, але вже
  // збережені позиції лишаються, тож перевірка потрібна й тут.
  const netM = metres(t.startLat, t.startLon, t.endLat, t.endLon);
  if (netM < 250 && t.distance < 2000) { drifted++; continue; }

  let startZone = zoneOf(t.startLat, t.startLon);
  const endZone = zoneOf(t.endLat, t.endLon);

  let originInferred = false;
  if (!startZone && carriedZone) {
    startZone = carriedZone;
    originInferred = true;
  }
  carriedZone = endZone || null;

  let classification = 'unclassified';
  let classified_by  = null;

  if (isPers(startZone) || isPers(endZone)) {
    classification = 'personal'; classified_by = 'geofence';
  } else if (isBiz(startZone) && isBiz(endZone)) {
    // дім є principal place of business компанії, тож старт звідти —
    // бізнес-поїздка, а не commuting
    classification = 'business'; classified_by = 'geofence';
  }

  // ЗАВЖДИ рахувати дату й годину в місцевій таймзоні. По UTC вечірня поїздка
  // о 21:00 ADT потрапляє в наступну добу, і дата в логбуку стає неправильною.
  const lp = localParts(t.startTime);
  const weekend = lp.weekday === 'Sat' || lp.weekday === 'Sun';
  const late = lp.hour >= 19 || lp.hour < 6;
  const unknown = !startZone && !endZone;

  // Провал звʼязку всередині поїздки. Раніше тут стояла здогадка «довго і
  // повільно», і вона не спіймала найгірший випадок: 22.09 телефон мовчав
  // 27 хвилин, за цей час авто проїхало 5 км до магазину і стояло там, а
  // Traccar видав одну поїздку замість двох, зшивши дірку прямою лінією.
  // Тепер міряємо дірку по самих позиціях - це факт, а не евристика.
  const durMin = (new Date(t.endTime) - new Date(t.startTime)) / 60000;
  const gap = worstGap(t.startTime, t.endTime);
  const stitched = gap.min >= 5 && gap.m >= 300;

  const reasons = [];
  if (stitched) reasons.push(`провал звʼязку ${Math.round(gap.min)} хв, стрибок ${(gap.m / 1000).toFixed(1)} км по прямій — відстань занижена, можливо це дві поїздки`);
  if (weekend) reasons.push('вихідний');
  if (late) reasons.push('позаробочий час');
  if (unknown) reasons.push('обидві точки поза geofence');
  if (originInferred) reasons.push('старт визначено за попередньою стоянкою');

  out.push({
    json: {
      vehicle_id: veh.vehicle_id,
      driver_id: veh.driver_id,
      traccar_trip_key: `${t.deviceId}:${t.startTime}`,
      started_at: t.startTime,
      ended_at: t.endTime,
      trip_date: lp.date,
      origin_address: t.startAddress || startZone || `${t.startLat}, ${t.startLon}`,
      destination_address: t.endAddress || endZone || `${t.endLat}, ${t.endLon}`,
      distance_km: Math.round((t.distance / 1000) * 100) / 100,
      classification,
      classified_by,
      classified_at: classified_by ? new Date().toISOString() : null,
      review_flag: reasons.length > 0,
      review_reason: reasons.join(', ') || null
    }
  });
}

if (drifted) {
  console.log(`Відкинуто ${drifted} псевдо-поїздок від дрейфу GPS на стоянці`);
}

return out;
